import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import { useExpiryClock } from '@/utils/dashboard/useExpiryClock';
import { isImageFile, isVideoFile } from '@/utils/mimeTypes';
import { formatExpiresAt, getExpiresAt, getExpiryState } from '@/utils/fileExpiry';
export default {
  name: 'FileListItem',
  setup() {
    return {
      expiryNow: useExpiryClock()
    };
  },
  props: {
    item: {
      type: Object,
      required: true
    },
    selected: {
      type: Boolean,
      default: false
    },
    fileLink: {
      type: String,
      default: ''
    }
  },
  emits: ['update:selected', 'enter', 'detail', 'copy', 'folderCopy', 'move', 'delete', 'download', 'touchstart', 'touchend', 'touchmove'],
  data() {
    return {
      localSelected: this.selected,
      tagColors: ['#f472b6', '#a78bfa', '#60a5fa', '#34d399']
    };
  },
  computed: {
    expiresAt() {
      return getExpiresAt(this.item?.metadata);
    },
    expiryState() {
      return getExpiryState(this.expiresAt, this.expiryNow);
    },
    expiryTitle() {
      if (this.expiresAt === null) return '';
      const time = formatExpiresAt(this.expiresAt, this.$i18n?.locale);
      if (this.expiryState === 'expired') return `${time} · ${this.$t('fileExpiry.expiredWaiting')}`;
      return this.$t(this.expiryState === 'soon' ? 'fileExpiry.expiresSoon' : 'fileExpiry.badge', {
        time
      });
    },
    isFolder() {
      // 检查 isFolder 属性或名称以 / 结尾
      return this.item.isFolder || this.item.name?.endsWith('/');
    },
    isVideo() {
      return isVideoFile(this.item);
    },
    isImage() {
      return isImageFile(this.item);
    },
    displayName() {
      if (this.isFolder) {
        const parts = this.item.name.split('/').filter(Boolean);
        return parts[parts.length - 1] || this.item.name;
      }
      return this.item.metadata?.FileName || this.getFileName(this.item.name);
    },
    fileNameStart() {
      const name = this.displayName;
      if (name.length <= 20) return name;
      return name.slice(0, -8);
    },
    fileNameEnd() {
      const name = this.displayName;
      if (name.length <= 20) return '';
      return name.slice(-8);
    },
    uploadDate() {
      if (this.item.uploaded) {
        return new Date(this.item.uploaded).toLocaleDateString();
      }
      if (this.item.metadata?.TimeStamp) {
        return new Date(this.item.metadata.TimeStamp).toLocaleDateString();
      }
      return '-';
    },
    fileSizeDisplay() {
      const sizeBytes = this.item.metadata?.FileSizeBytes;
      const sizeMB = this.item.metadata?.FileSize;
      if (sizeBytes) {
        if (sizeBytes < 1024) {
          return `${sizeBytes} B`;
        } else if (sizeBytes < 1024 * 1024) {
          return `${(sizeBytes / 1024).toFixed(1)} KB`;
        } else {
          return `${(sizeBytes / 1024 / 1024).toFixed(2)} MB`;
        }
      } else if (sizeMB) {
        return `${sizeMB} MB`;
      }
      return '-';
    }
  },
  watch: {
    selected(val) {
      this.localSelected = val;
    }
  },
  methods: {
    handleSelectChange(value) {
      this.localSelected = value;
      this.$emit('update:selected', value);
    },
    handlePreviewClick() {
      if (this.isFolder) {
        this.$emit('enter');
      } else {
        this.$emit('detail');
      }
    },
    getFileName(name) {
      const parts = (name || '').split('/');
      return parts[parts.length - 1];
    },
    getTagColor(index) {
      return this.tagColors[index % this.tagColors.length];
    }
  }
};