import { useExpiryClock } from '@/utils/dashboard/useExpiryClock';
import { isImageFile, isVideoFile, isAudioFile } from '@/utils/mimeTypes';
import { formatExpiresAt, getExpiresAt, getExpiryState } from '@/utils/fileExpiry';
export default {
  name: 'FileCard',
  setup() {
    return {
      expiryNow: useExpiryClock()
    };
  },
  props: {
    item: {
      type: Object,
      required: true
    },
    selected: {
      type: Boolean,
      default: false
    },
    fileLink: {
      type: String,
      required: true
    },
    previewSrcList: {
      type: Array,
      default: () => []
    },
    disableTooltip: {
      type: Boolean,
      default: false
    }
  },
  emits: ['update:selected', 'detail', 'copy', 'move', 'delete', 'download', 'touchstart', 'touchend', 'touchmove'],
  data() {
    return {
      localSelected: this.selected,
      videoLoading: true,
      videoError: false
    };
  },
  computed: {
    expiresAt() {
      return getExpiresAt(this.item?.metadata);
    },
    expiryState() {
      return getExpiryState(this.expiresAt, this.expiryNow);
    },
    expiryTitle() {
      if (this.expiresAt === null) return '';
      const time = formatExpiresAt(this.expiresAt, this.$i18n?.locale);
      if (this.expiryState === 'expired') return `${time} · ${this.$t('fileExpiry.expiredWaiting')}`;
      return this.$t(this.expiryState === 'soon' ? 'fileExpiry.expiresSoon' : 'fileExpiry.badge', {
        time
      });
    },
    channelTag() {
      return this.item.channelTag || '';
    },
    isVideo() {
      return isVideoFile(this.item);
    },
    isAudio() {
      return isAudioFile(this.item);
    },
    isImage() {
      return isImageFile(this.item);
    },
    displayName() {
      const fileName = this.item.metadata?.FileName || this.item.name || '';
      const parts = fileName.split('/');
      return parts[parts.length - 1];
    }
  },
  watch: {
    selected(val) {
      this.localSelected = val;
    },
    fileLink() {
      // 链接变化时重置加载状态
      this.videoLoading = true;
      this.videoError = false;
    }
  },
  methods: {
    handleVideoError() {
      this.videoLoading = false;
      this.videoError = true;
    },
    handleVideoClick(e) {
      const video = e.target;
      if (video.requestFullscreen) {
        video.requestFullscreen();
      } else if (video.webkitRequestFullscreen) {
        video.webkitRequestFullscreen();
      } else if (video.mozRequestFullScreen) {
        video.mozRequestFullScreen();
      } else if (video.msRequestFullscreen) {
        video.msRequestFullscreen();
      }
    },
    handleFullscreenChange(e) {
      const video = e.target;
      const isFullscreen = document.fullscreenElement || document.webkitFullscreenElement || document.mozFullScreenElement || document.msFullscreenElement;
      if (isFullscreen) {
        // 进入全屏：取消静音和循环
        video.muted = false;
        video.loop = false;
      } else {
        // 退出全屏：恢复静音和循环，暂停并重置
        video.muted = true;
        video.loop = true;
        video.pause();
        video.currentTime = 0;
      }
    },
    handleVideoHover(e, isEnter) {
      const video = e.target;
      if (isEnter) {
        video.play().catch(() => {});
      } else {
        video.pause();
        video.currentTime = 0;
      }
    }
  }
};